int done = 0;
pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t  c = PTHREAD_COND_INITIALIZER;

void thr_exit(void) {
    pthread_mutex_lock(&m);
    done = 1;
    pthread_cond_signal(&c);
    pthread_mutex_unlock(&m);
}

void thr_join(void) {
    pthread_mutex_lock(&m);
    while (done == 0)
        pthread_cond_wait(&c, &m);
    pthread_mutex_unlock(&m);
}

int buffer[MAX];
int fill_ptr = 0, use_ptr = 0, count = 0;

pthread_mutex_t m     = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t  empty = PTHREAD_COND_INITIALIZER;   /* producers wait here */
pthread_cond_t  fill  = PTHREAD_COND_INITIALIZER;   /* consumers wait here */

void producer(int value) {
    pthread_mutex_lock(&m);
    while (count == MAX)
        pthread_cond_wait(&empty, &m);
    buffer[fill_ptr] = value;
    fill_ptr = (fill_ptr + 1) % MAX;
    count++;
    pthread_cond_signal(&fill);
    pthread_mutex_unlock(&m);
}

int consumer(void) {
    pthread_mutex_lock(&m);
    while (count == 0)
        pthread_cond_wait(&fill, &m);
    int value = buffer[use_ptr];
    use_ptr = (use_ptr + 1) % MAX;
    count--;
    pthread_cond_signal(&empty);
    pthread_mutex_unlock(&m);
    return value;
}

sem_t empty, full, mutex;

sem_init(&empty, 0, MAX);   /* MAX slots are free */
sem_init(&full,  0, 0);     /* nothing to consume yet */
sem_init(&mutex, 0, 1);     /* a binary semaphore used as a lock */

void put(int value) {
    sem_wait(&empty);
    sem_wait(&mutex);
    buffer[fill_ptr] = value;
    fill_ptr = (fill_ptr + 1) % MAX;
    sem_post(&mutex);
    sem_post(&full);
}

int get(void) {
    sem_wait(&full);
    sem_wait(&mutex);
    int value = buffer[use_ptr];
    use_ptr = (use_ptr + 1) % MAX;
    sem_post(&mutex);
    sem_post(&empty);
    return value;
}

void transfer(account_t *from, account_t *to, int amount) {
    pthread_mutex_lock(&from->lock);
    pthread_mutex_lock(&to->lock);        /* the circular wait lives here */
    from->balance -= amount;
    to->balance   += amount;
    pthread_mutex_unlock(&to->lock);
    pthread_mutex_unlock(&from->lock);
}

void transfer_ordered(account_t *from, account_t *to, int amount) {
    account_t *first  = (from < to) ? from : to;
    account_t *second = (from < to) ? to   : from;
    pthread_mutex_lock(&first->lock);
    pthread_mutex_lock(&second->lock);
    from->balance -= amount;
    to->balance   += amount;
    pthread_mutex_unlock(&second->lock);
    pthread_mutex_unlock(&first->lock);
}

